"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def longestSubstringLength(str):
    n = len(str)
    seen = set()
    maxLen = 0
    left = 0
    for right in range(0, n):
        while (str[right] in seen):
            seen.remove(str[left])
            left = (left + 1)
        seen.add(str[right])
        maxLen = max(maxLen, ((right - left) + 1))
    return maxLen
print(longestSubstringLength("abcabcbb"))